#!/usr/bin/env bash
# Sekretär-Serie 19.11.2026 abends: je Quelle Leitfaden, danach Metadaten (batch.py findet den Leitfaden selbst).
# Nur lesend gegenüber der DB, schreibt nur in scripts/agent/output/<lauf>/. Review und apply.py macht Julian danach.
# Start (Shell, Repo-Wurzel):  caffeinate -i bash scripts/agent/serie_2026-11-19_abend.sh
cd "$(dirname "$0")/../.." || exit 1
LOG="logs/sekretaer_serie_2026-11-19_abend.log"
declare -a ERG=()

quelle() {  # $1 Präfix, $2 Budget Leitfaden, $3 Auftrag
  local src="$1" thema="$(echo "$1" | tr 'A-Z' 'a-z')_leitfaden"
  echo "=== $(date +%H:%M) Leitfaden $src" | tee -a "$LOG"
  python3 scripts/agent/secretary.py "$3" --thema "$thema" --budget "$2" --max-turns 120 2>&1 | tee -a "$LOG"
  local d; d=$(ls -d scripts/agent/output/*_sekretaer_"$thema" 2>/dev/null | sort | tail -1)
  if [ -z "$d" ] || [ ! -f "$d/leitfaden.md" ] || ! grep -q "Status: success" "$d/protokoll.md"; then
    ERG+=("$src: Leitfaden NICHT regulär fertig ($d) – Metadaten übersprungen"); return
  fi
  echo "=== $(date +%H:%M) Metadaten $src" | tee -a "$LOG"
  python3 scripts/agent/batch.py "$src" --paket 40 --anzahl 1 2>&1 | tee -a "$LOG"
  ERG+=("$src: Leitfaden ok ($(basename "$d")), batch Exit ${PIPESTATUS[0]}")
}

G="Schreibe den Quellen-Leitfaden (leitfaden.md und leitfaden_belege.md) und befunde.md mit Länder-Stichprobe DB gegen Rohdatei für DEU, USA, JPN, BRA, NGA (wo vorhanden). Keine metadata.sql. Lies zuerst den Loader (read_text mit Pfad ab Repo-Wurzel, scripts/pipeline/...), damit du weißt, was genau geladen und gerechnet wurde, und prüf per sql_query, welche Codes und Jahre (time_period) in der DB stehen. Methodik nur mit Beleg (Datei und Zeile oder abgerufene URL), nicht aus dem Gedächtnis; was nicht belegt ist, als offen markieren. Belege außerhalb des Referenzordners mit Pfad ab Repo-Wurzel angeben. Abschnitt 7: ein Steckbrief je DB-Code mit dem Wortlaut der Quelle, soweit belegt; bei Codes, die erst unser Loader berechnet, die Rechnung aus dem Loader beschreiben (mit Zeile)."

quelle ATOP 1.2 "ATOP (Alliance Treaty Obligations and Provisions, Version 5.1, Leeds et al., 6 Codes n_alliances, has_defense, has_offense, has_neutral, has_nonagg, has_consul). Loader: scripts/pipeline/international/load_atop.py (Staat-Jahr-Datei atop5_1sy.csv). Rohdaten: data/raw/Manuell_27-05/ATOP 5.1 (.csv)/ (atop5_1sy.csv und die anderen Ebenen). Codebuch: data/raw/Manuell_27-05/ATOP/atop_5_1_codebook.pdf (pdf_to_text). Pflichtfragen: (1) Was ist ein Bündnis laut ATOP (Aufnahmekriterien). (2) Was bedeuten die fünf Verpflichtungsarten (defense, offense, neutrality, nonaggression, consultation) laut Codebuch. (3) Was zählt n_alliances genau (Variable der sy-Datei oder Rechnung des Loaders) und wie werden 0/1-Codes gebildet. (4) Jahre, Ländercodes (COW-Nummern) und deren Zuordnung im Loader. (5) Zitierweise und Nutzungsbedingungen. $G"

quelle UNVOTE 1.8 "UNVOTE (Abstimmungen der UN-Generalversammlung, 16 Codes wie yes_share, agree_usa, yes_human_rights, minority_share). Alle Codes berechnet unser Loader selbst: scripts/pipeline/international/load_un_voting.py sowie load_un_voting_1_core.py, _2_alignment.py, _3_minority.py, _4_themes.py. Rohdatei: data/raw/Manuell_27-05/2026_02_06_ga_voting.csv (UN Digital Library, Export 06.02.2026; öffne Kopf und einige Zeilen). Pflichtfragen: (1) Herkunft und Aufbau der Rohdatei (Quelle, Stand, eine Zeile = ?). (2) Je Code die genaue Rechnung aus dem Loader: Zähler, Nenner, Umgang mit Enthaltung und Nichtteilnahme, Jahr oder Sitzungsperiode. (3) agree_*: Definition von Übereinstimmung und wie EU und BRICS als Gruppe gebildet werden (welche Mitglieder, ab wann). (4) Themen-Codes: wie eine Resolution einem Thema zugeordnet wird (Feld der Quelle oder Stichwörter im Loader). (5) minority_share: Definition. Prüfe einen Wert für ein Land-Jahr an der Rohdatei nach, wenn das mit vertretbarem Aufwand geht. $G"

quelle PEW_REL 1.2 "PEW_REL (Pew Research Center, Religious Composition 2010-2020, 8 Codes christians, muslims, unaffiliated, buddhists, hindus, jews, other_religions, rdi). Loader: scripts/pipeline/culture/load_pew_religion.py (liest die ZIP; der Pfad im Loader zeigt auf data/raw/Manuell_27-05/, die Datei liegt heute in data/raw/culture/ – nur festhalten). Lesbare Auszüge im Referenzordner: pew_religion_2010_2020_README.txt, pew_religion_2010_2020_percentages.csv, pew_religion_2010_2020_diversity.csv (aus der ZIP entpackt, unverändert). Methodik per WebFetch von pewresearch.org (Bericht How the Global Religious Landscape Changed 2010-2020, Methodology). Pflichtfragen: (1) Was ist jede Kategorie (wer zählt als unaffiliated, was steckt in other_religions). (2) Anteil der Gesamtbevölkerung in Prozent? Jahre 2010 und 2020 – Schätzung oder Erhebung (Zensus, Umfragen, Modell). (3) rdi: Religious Diversity Index, wie berechnet, Skala. (4) Nutzungsbedingungen. $G"

quelle WHR 1.2 "WHR (World Happiness Report 2026, Daten zu Figure 2.1, 7 Codes life_evaluation, gdp_component, social_support, health, freedom, generosity, corruption). Loader: scripts/pipeline/culture/load_whr.py. Rohdatei: data/raw/culture/WHR26_Data_Figure_2.1.xlsx, lesbar als data/raw/reference/whr26_data_figure_2_1.csv (Blatt 'Data for Figure 2.1 (2011–2025)', unverändert exportiert). Methodik per WebFetch von worldhappiness.report (Kapitel 2 und Statistical Appendix). Pflichtfragen: (1) life_evaluation: Cantril-Leiter 0-10, Gallup World Poll, 3-Jahres-Mittel – welche Jahre stecken in einem Wert und was steht in time_period. (2) Die sechs Explained-by-Codes sind Erklärungsanteile aus einer Regression, keine Messungen: wie gerechnet, warum sie sich nicht mit den Rohgrößen vergleichen lassen, Bezug zur Dystopia. (3) Rang und Konfidenzband (Lower/Upper whisker) – nicht geladen, nur festhalten. (4) Nutzungsbedingungen. $G"

quelle UNHCR 1.2 "UNHCR (UNHCR Refugee Data Finder / Population Statistics API, 6 Codes asylum_seekers, refugees_origin, refugees_asylum, idps, stateless, returned_refugees). Loader: scripts/pipeline/demographics/load_unhcr.py (API https://api.unhcr.org/population/v1/). Hole für die Stichprobe mit download_file die API-Antwort für die fünf Länder und ein Jahr (Parameter wie im Loader). Methodik per WebFetch von unhcr.org/refugee-statistics (Methodology, Definitions). Pflichtfragen: (1) Definition jeder Gruppe (Flüchtlinge unter UNHCR-Mandat, ohne UNRWA-Palästinenser? Asylsuchende, Binnenvertriebene nur IDMC/UNHCR-betreut?, Staatenlose). (2) Herkunftsland gegen Aufnahmeland: welcher Code zählt was. (3) Stichtag (Jahresende) und Revisionen. (4) Nutzungsbedingungen (Lizenz). $G"

quelle ACLED 1.2 "ACLED (Armed Conflict Location & Event Data, 5 Codes political_violence_events, fatalities, demonstration_events, civilian_targeting_events, civilian_fatalities). Loader: scripts/pipeline/governance/load_acled.py (liest Länder-Jahr-xlsx-Dateien 'as-of-03Jul2026'). Rohdaten: data/raw/governance/ACLED/ – dort liegt heute nur die Datei für demonstration_events; lesbar als data/raw/reference/acled_demonstration_events_country_year_2026-07-03.csv. Dass die übrigen Dateien fehlen, in befunde.md festhalten. Methodik per WebFetch von acleddata.com (Codebook, Event Types, Fatalities, Methodology). Pflichtfragen: (1) Definition jeder Ereignisart und wie die fünf Codes darauf abgebildet sind. (2) Wie ACLED Todesopfer zählt und schätzt (konservative Schätzung, Revisionen). (3) Abdeckung: ab welchem Jahr je Land (ACLED ist nicht für alle Länder gleich lang) – das ist wichtig für Zeitvergleiche. (4) Nutzungsbedingungen (ACLED verlangt Registrierung und hat eigene Bedingungen). $G"

quelle WEF 1.0 "WEF (Global Gender Gap Index des World Economic Forum, 5 Codes gggi_ggi, gggi_eas, gggi_hss, gggi_pes, gggi_pos). Der Loader scripts/pipeline/governance/load_gender_gap.py lädt die Werte nicht vom WEF, sondern aus dem QoG Standard Dataset (qog_std_cs_jan25.csv, Quality of Government Institute, Universität Göteborg): QoG ist die Bezugsquelle, das WEF der Urheber. Codebuch per download_file: QoG Standard Codebook Januar 2025 von qogdata.pol.gu.se (Einträge gggi_*). Methodik des Index per WebFetch von weforum.org (Global Gender Gap Report, Methodology). Pflichtfragen: (1) Bedeutung der vier Teilindizes und des Gesamtindex, Skala 0-1 (1 = Parität). (2) Welches Berichtsjahr steckt in der QoG-Querschnittsdatei und was steht in time_period. (3) Was QoG an den Werten ändert (nichts oder Umbenennung). (4) Nutzungsbedingungen von QoG und WEF. $G"

echo; echo "===== Zusammenfassung =====" | tee -a "$LOG"
printf '%s\n' "${ERG[@]}" | tee -a "$LOG"
echo "Morgen: python3 scripts/agent/status.py, dann review.py und apply.py je Lauf" | tee -a "$LOG"
